import{_ as p,a0 as l,w as o,s as r,ao as d,I as n,x as a,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"通過 Linux 命令列連接 Wifi | LCTT x X-CMD","titleTemplate":false,"description":"通過 Linux 命令列連接 Wifi | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通過 Linux 命令列連接 Wifi | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通過 Linux 命令列連接 Wifi | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171002 Connect To Wifi From The Linux Command Line","title":"通過 Linux 命令列連接 Wifi","tag":"201801","desc":""},"relativePath":"201801/20171002 Connect To Wifi From The Linux Command Line.md","filePath":"[post].md"}'),h={name:"201801/20171002 Connect To Wifi From The Linux Command Line.md"};function c(u,i,g,k,f,b){const s=l("Link");return o(),r("div",null,[i[13]||(i[13]=d(`<h1 id="通過-linux-命令列連接-wifi" tabindex="-1">通過 Linux 命令列連接 Wifi <a class="header-anchor" href="#通過-linux-命令列連接-wifi" aria-label="Permalink to “通過 Linux 命令列連接 Wifi”">​</a></h1><p>目標：僅使用命令列工具來配置 WiFi</p><p>發行版：適用主流的那些發行版</p><p>要求：安裝了無線網卡的 Linux 並且擁有 root 權限。</p><p>難度：簡單</p><p>約定：</p><ul><li><code>#</code> - 需要使用 root 權限來執行指定命令，可以直接使用 root 用户來執行，也可以使用 <code>sudo</code> 命令</li><li><code>$</code> - 可以使用普通用户來執行指定命令</li></ul><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>許多人喜歡用圖形化的工具來管理電腦，但也有很多人不喜歡這樣做。如果你比較喜歡命令列工具，管理 WiFi 會是件很痛苦的事情。然而，事情本不該如此。</p><p>wpa_supplicant 可以作為命令列工具來用。使用一個簡單的配置文件就可以很容易設置號 WiFi。</p><h3 id="掃描網絡" tabindex="-1">掃描網絡 <a class="header-anchor" href="#掃描網絡" aria-label="Permalink to “掃描網絡”">​</a></h3><p>若你已經知道了網絡的信息，就可以跳過這一步。如果不瞭解的話，則這是一個找出網絡信息的好方法。</p><p>wpa_supplicant 中有一個工具叫做 <code>wpa_cli</code>，它提供了一個命令列接口來管理你的 WiFi 連接。事實上你可以用它來設置任何東西，但是設置一個配置文件看起來要更容易一些。</p><p>使用 root 權限運行 <code>wpa_cli</code>，然後掃描網絡。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wpa_cli</span></span>
<span class="line"><span>&gt; scan</span></span></code></pre></div><p>掃描過程要花上一點時間，並且會顯示所在區域的那些網絡。記住你想要連接的那個網絡。然後輸入 <code>quit</code> 退出。</p><h3 id="生成配置塊並且加密你的密碼" tabindex="-1">生成配置塊並且加密你的密碼 <a class="header-anchor" href="#生成配置塊並且加密你的密碼" aria-label="Permalink to “生成配置塊並且加密你的密碼”">​</a></h3><p>還有更方便的工具可以用來設置配置文件。它接受網絡名稱和密碼作為參數，然後生成一個包含該網路配置塊（其中的密碼被加密處理了）的配置文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># wpa_passphrase networkname password &gt; /etc/wpa_supplicant/wpa_supplicant.conf</span></span></code></pre></div><h3 id="裁剪你的配置" tabindex="-1">裁剪你的配置 <a class="header-anchor" href="#裁剪你的配置" aria-label="Permalink to “裁剪你的配置”">​</a></h3><p>現在你已經有了一個配置文件了，這個配置文件就是 <code>/etc/wpa_supplicant/wpa_supplicant.conf</code>。其中的內容並不多，只有一個網絡塊，其中有網絡名稱和密碼，不過你可以在此基礎上對它進行修改。</p><p>用喜歡的編輯器打開該文件，首先刪掉説明密碼的那行註釋。然後，將下面行加到配置最上方。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ctrl_interface=DIR=/var/run/wpa_supplicant GROUP=wheel</span></span></code></pre></div><p>這一行只是讓 <code>wheel</code> 組中的用户可以管理 wpa_supplicant。這會方便很多。</p><p>其他的內容則添加到網絡塊中。</p><p>如果你要連接到一個隱藏網絡，你可以添加下面行來通知 wpa_supplicant 先掃描該網絡。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>scan_ssid=1</span></span></code></pre></div><p>下一步，設置協議以及密鑰管理方面的配置。下面這些是 WPA2 相關的配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>proto=RSN</span></span>
<span class="line"><span>key_mgmt=WPA-PSK</span></span></code></pre></div><p><code>group</code> 和 <code>pairwise</code> 配置告訴 wpa_supplicant 你是否使用了 CCMP、TKIP，或者兩者都用到了。為了安全考慮，你應該只用 CCMP。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>group=CCMP</span></span>
<span class="line"><span>pairwise=CCMP</span></span></code></pre></div><p>最後，設置網絡優先級。越高的值越會優先連接。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>priority=10</span></span></code></pre></div><p><img src="https://linuxconfig.org/images/wpa-cli-config.jpg" alt="Complete WPA_Supplicant Settings"></p><p>保存配置然後重啓 wpa_supplicant 來讓改動生效。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>當然，該方法並不是用於即時配置無線網絡的最好方法，但對於定期連接的網絡來説，這種方法非常有效。</p><hr>`,38)),n("p",null,[i[1]||(i[1]=a("via: ",-1)),e(s,{href:"https://linuxconfig.org/connect-to-wifi-from-the-linux-command-line"},{default:t(()=>[...i[0]||(i[0]=[a("https://linuxconfig.org/connect-to-wifi-from-the-linux-command-line",-1)])]),_:1})]),n("p",null,[i[5]||(i[5]=a("作者：",-1)),e(s,{href:"https://linuxconfig.org"},{default:t(()=>[...i[2]||(i[2]=[a("Nick Congleton",-1)])]),_:1}),i[6]||(i[6]=a(" 譯者：",-1)),e(s,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[3]||(i[3]=[a("lujun9972",-1)])]),_:1}),i[7]||(i[7]=a(" 校對：",-1)),e(s,{href:"https://github.com/wxy"},{default:t(()=>[...i[4]||(i[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[i[10]||(i[10]=a("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[8]||(i[8]=[a("LCTT",-1)])]),_:1}),i[11]||(i[11]=a(" 原創編譯，",-1)),e(s,{href:"https://linux.cn/"},{default:t(()=>[...i[9]||(i[9]=[a("Linux中國",-1)])]),_:1}),i[12]||(i[12]=a(" 榮譽推出",-1))])])}const T=p(h,[["render",c]]);export{x as __pageData,T as default};
